#!/usr/bin/env bash
set -euo pipefail

_LIB_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
# shellcheck source=bin/_agents/_lib.sh
source "$_LIB_DIR/_lib.sh"

RULES_ROOT_DIR="$1"
SKILLS_ROOT_DIR="$2"
BASE_DIR="${3:-.}"
EXCLUSIVE_ROOT_DIR="${4:-}"
# If BASE_DIR is empty (passed as ""), default to .
if [[ -z "$BASE_DIR" ]]; then
  BASE_DIR="."
fi

CLEAN="${5:-false}"

# Kiro uses .kiro/steering/ for all files
STEERING_DIR="$BASE_DIR/.kiro/steering"
MANIFEST="$BASE_DIR/.kiro/.agentx-manifest"

# With --clean, remove files generated by the previous run (per the
# manifest) before regenerating.
if [[ "$CLEAN" == "true" ]]; then
  manifest_clean "$MANIFEST" "$BASE_DIR" "$STEERING_DIR"
fi

mkdir -p "$STEERING_DIR"
manifest_init "$MANIFEST"

process_rules() {
  local src_dir="$1"

  if [[ ! -d "$src_dir" ]]; then return; fi

  while IFS= read -r -d '' rule_file; do
    local rel_path filename output_file trigger description
    rel_path="${rule_file#"$src_dir"/}"
    
    # Replace slashes with hyphens to make clear names (e.g. flutter-performance.md)
    filename="${rel_path//\//-}"
    output_file="$STEERING_DIR/$filename"

    trigger="$(fm_field "$rule_file" trigger)"
    trigger="${trigger:-always}"
    description="$(fm_field "$rule_file" description)"

    {
      echo "---"
      case "$trigger" in
        always)
          echo "inclusion: always"
          ;;
        auto)
          echo "inclusion: auto"
          echo "name: ${filename%.md}"
          [[ -n "$description" ]] && echo "description: $description"
          ;;
        off)
          echo "inclusion: manual"
          ;;
        *)
          echo "Error: unknown trigger '$trigger' in $rule_file" >&2
          exit 1
          ;;
      esac
      echo "---"
      echo ""
      fm_body "$rule_file"
    } > "$output_file"
    record_generated "$MANIFEST" "$BASE_DIR" "$output_file"
  done < <(find "$src_dir" -name "*.md" -print0)
}

process_skills() {
  local src_dir="$1"
  
  if [[ ! -d "$src_dir" ]]; then return; fi
  
  while IFS= read -r -d '' skill_file; do
    local skill_name output_file description
    skill_name="$(basename "$(dirname "$skill_file")")"
    output_file="$STEERING_DIR/${skill_name}.md"
    
    description="$(fm_field "$skill_file" description)"
    
    {
      echo "---"
      if [[ -n "$description" ]]; then
        echo "inclusion: auto"
        echo "name: $skill_name"
        echo "description: $description"
      else
        echo "inclusion: manual"
      fi
      echo "---"
      echo ""
      fm_body "$skill_file"
    } > "$output_file"
    record_generated "$MANIFEST" "$BASE_DIR" "$output_file"
  done < <(find "$src_dir" -name "SKILL.md" -print0)
}

# 1. Process Core Rules
process_rules "$RULES_ROOT_DIR"

# 2. Process Core Skills
process_skills "$SKILLS_ROOT_DIR"

# 3. Process Exclusive content if provided
if [[ -n "$EXCLUSIVE_ROOT_DIR" ]] && [[ -d "$EXCLUSIVE_ROOT_DIR" ]]; then
  echo "Applying exclusive content from: $EXCLUSIVE_ROOT_DIR"
  process_rules "$EXCLUSIVE_ROOT_DIR/rules"
  process_skills "$EXCLUSIVE_ROOT_DIR/skills"
fi

echo "Kiro generation complete."
